from pathlib import Path
import json,csv,shutil
R=Path(__file__).resolve().parents[1];O=R/'outputs/LeLovophon_Direct_Gear_Prototype/Reality_Audit'
raw=json.loads((O/'Static_All_Pairs_Raw.json').read_text());hits=raw['positive_volume_intersections'];motion=json.loads((O/'Motion_to_Stationary_Audit.json').read_text());heights=json.loads((O/'String_Support_and_Height_Audit.json').read_text());faces=json.loads((O/'Critical_Face_Clearances.json').read_text())
strings=[x for x in hits if 'KotoSpeakingString' in x['a']+x['b'] and 'RearPivotStay' in x['a']+x['b']]
input_clashes=[x for x in hits if 'Common5mmInputShaft' in [x['a'],x['b']] and 'InputBearingShelf' in x['a']+x['b']]
pivot_clashes=[x for x in hits if '_3mmShaft_0' in x['a']+x['b'] and '_RearPivotStay' in x['a']+x['b']]
anchor_clashes=[x for x in hits if 'LeftNylonOverEdge' in x['a']+x['b'] and 'NylonAnchorEndPlate' in [x['a'],x['b']]]
washer_clashes=[x for x in hits if 'PinRetainingWasher' in x['a']+x['b'] and any(t in x['a']+x['b'] for t in ['CrankPin','RockerPin'])]
failures=[dict(id='F01',status='Confirmed interference',finding='Diagonal supports intersect speaking strings',count=len(strings),consequence='Seven solid intersections on the five lowest strings obstruct the modeled vibrating lengths.'),dict(id='F02',status='Confirmed interference',finding='Input bearing shelves intersect the common rotating shaft',count=len(input_clashes),consequence='The shelf tubes terminate at the shaft axis instead of at a clear outer bearing housing.'),dict(id='F03',status='Confirmed interference',finding='Rear pivot stays intersect pivot shafts and bearings',count=len(pivot_clashes),consequence='All twelve pivots are obstructed by their own stationary support tubes.'),dict(id='F04',status='Confirmed motion interference',finding='Moving arms strike neighbouring pivot shafts',count=len(motion['unexpected_intersection_pairs']),consequence='These contacts arise during the swept motion and are absent at common zero.'),dict(id='F05',status='Confirmed interference',finding='Anchor string tails run inside the solid end plate',count=len(anchor_clashes),consequence='The routing is not a clear path through the modeled anchor holes.'),dict(id='F06',status='Confirmed dimensional conflict',finding='Retaining washer holes are smaller than the passing pin bodies',count=len(washer_clashes),consequence='1.7 mm washer bores overlap 3 mm pins; shoulder/retention design is unfinished.'),dict(id='F07',status='Confirmed unsupported/interfering geometry',finding='Outer third bridges miss the soundboard',count=2,consequence='Both bridge feet are 4 mm from the board; high D5 has no board underneath, while low C3 also intersects the anchor block.'),dict(id='F08',status='Confirmed geometry; acoustic consequence untested',finding='Zero string break angle at third bridges',count=12,consequence='No static downbearing from string tension is defined; a stable speaking-length boundary and reliable soundboard coupling are not established.'),dict(id='F09',status='Confirmed zero-clearance contact; thrust design unresolved',finding='Crank flanges have zero separation from fixed front carriers/bearing faces',count=12,consequence='Requires a defined bearing/thrust/spacer stack. Zero-volume contact alone does not prove that it will bind or run acceptably.'),dict(id='F10',status='Incomplete engineering, not a geometric impossibility claim',finding='Shaft torque locking, phase adjustment, fits and fastening not detailed',count='',consequence='Round bores, overlapping attachment reservations and placeholders are not a complete power-transmitting assembly.' )]
summary=dict(date='2026-11-09',model='Axle_Clearance_Revision/LeLovophon_Direct_Gear_Prototype.FCStd',build_status='FAIL — not buildable as drawn; no physical validation',failures=failures,static_pairs_examined=raw['tested_pairs'],raw_static_overlap_count=len(hits),raw_overlap_warning='Includes intentional press-fit/joinery/attachment reservations; not 304 independent design failures.',motion_poses_per_voice=motion['poses_per_voice'],motion_scope=motion['scope'],physical_pass=False)
